const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const titles=arr(input.sheets).map(s=>String(((s||{}).properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(const off of [0,-1]){ const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+off,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t); }
const q=s=>"'"+s+"'";
const f=[{a1Range:"'שימורים לטלי'!A1:Q3000"}];
tabs.forEach(t=>f.push({a1Range:q(t)+'!A1:Z1500'}));
return {tabs:JSON.stringify(tabs), readBody:JSON.stringify({dataFilters:f, valueRenderOption:'FORMATTED_VALUE'})};

// Tali retention (שימורים) checker – Steve 09/11/2026:
// a cancelled / fallen customer the rep did not explain within 24h moves to 'שימורים לטלי';
// Tali gets the new ones + a daily reminder; if a row has no update from Tali for 24h, Yarden and Steve get an alert.
// If Tali marks שומר, the deal is fully hers.
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const digits=s=>String(s==null?'':s).replace(/\D/g,'');
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const vr=arr(input.vr).map(v=>(v&&v.valueRange)||v||{});
const byName=n=>{ const x=vr.find(v=>{ const r=norm(v.range).replace(/^'/,''); return r.startsWith(n+"'!")||r.startsWith(n+'!'); }); return (x&&x.values)||[]; };
const tabs=arr(input.tabs).map(norm);
const TALI='972525102820', MGR=[['סטיב','972544604246'],['ירדן','972504445169']];
const T="'שימורים לטלי'";
const pad=n=>('0'+n).slice(-2);
const nowIL=input.now?new Date(input.now):new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const stamp=d=>d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes());
const nowS=stamp(nowIL); const todayIso=nowS.slice(0,10); const dm=pad(nowIL.getDate())+'/'+pad(nowIL.getMonth()+1);
const parseS=s=>{ const m=norm(s).match(/^(\d{4})-(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2})/); return m?new Date(+m[1],+m[2]-1,+m[3],+m[4],+m[5]):null; };
const hrs=(a,b)=>(b-a)/3600000;
const dow=nowIL.getDay(), H=nowIL.getHours();
const quiet=dow===6||(dow===5&&H>=16)||H<8||H>=20;
const colL=n=>{ let s=''; n++; while(n>0){ const k=(n-1)%26; s=String.fromCharCode(65+k)+s; n=Math.floor((n-1)/26); } return s; };
const ALIAS={'אוסי':'אוסי גיאן','אופק פ':'אופק','דוד':'דוד חי','איתמר':'איתמר ששון'};
const tt=byName('שימורים לטלי');
const writes=[]; const msgs=[];
const HEAD=['תאריך העברה','מספר לקוח','שם לקוח','נייד','נציג','מה קרה','סטטוס טלי','הערת טלי','עדכון אחרון','שעות בלי עדכון','נשלח לטלי','התראת חריגה לירדן וסטיב','העסקה נזקפת ל','מקור (לא לגעת)','חתימה (לא לגעת)'];
if(!tt.length){ writes.push({range:T+'!A1:O1', values:[HEAD]}); tt.push(HEAD); }
const have=new Set(tt.slice(1).map(r=>norm((r||[])[13])).filter(Boolean));
let next=Math.max(tt.length,1)+1;
const fresh=[];
// 1) escalate: rep got the cancellation message (marker ⏳ DD/MM in 'הסבר נציג') and did not answer within 24h
tabs.forEach(tb=>{ const rows=byName(tb); const hd=(rows[0]||[]).map(norm);
  const hE=hd.findIndex(x=>x.startsWith('הסבר נציג')); if(hE<0) return;
  const hN=hd.findIndex(x=>x.startsWith('הערות')); const iN=hN>=0?hN:17;
  rows.forEach((r,i)=>{ if(i===0||!r) return; const ev=norm(r[hE]);
    const mk=ev.match(/^⏳\D*(\d{1,2})\/(\d{1,2})/); if(!mk) return;
    let y=nowIL.getFullYear(); if(+mk[2]>nowIL.getMonth()+1) y--;
    const sent=new Date(y,+mk[2]-1,+mk[1],9,0);
    if(hrs(sent,nowIL)<23) return; // escalate from 08:00 the next day, before the 09:00 rep message could send a reminder
    const src="'"+tb+"'!"+colL(hE)+(i+1);
    if(!have.has(src)){
      const rep=norm(r[7]); const why=/בוטל|ביטול|ביטל|לא מעוניין/.test(norm(r[iN]))?'בוטל':'ההתקנה נפלה / סומן באדום';
      const row=[nowS, digits(r[6]), norm(r[2]), norm(r[3]), ALIAS[rep]||rep, why+' (חודש '+tb+')', '', '', nowS, 0, '', '', '', src, '|'];
      writes.push({range:T+'!A'+next+':O'+next, values:[row]}); tt.push(row); next++; have.add(src); fresh.push(row);
    }
    writes.push({range:src, values:[['➡️ הועבר לטלי '+dm+' – הנציג לא ענה תוך 24 שעות']]});
  }); });
// 2) follow-up on Tali's rows
const FINAL=/^(שומר|לא שומר|לא רלוונטי)/;
const openL=[], newL=[], breachL=[];
tt.forEach((r,i)=>{ if(i===0||!r) return; const name=norm(r[2]); if(!name&&!norm(r[1])) return;
  const rn=i+1; const st=norm(r[6]), note=norm(r[7]); const sig=st+'|'+note; let last=parseS(r[8])||parseS(r[0])||nowIL;
  if(sig!==norm(r[14])){ last=nowIL; writes.push({range:T+'!I'+rn, values:[[nowS]]}); writes.push({range:T+'!O'+rn, values:[[sig]]});
    const saved=/^שומר/.test(st);
    writes.push({range:T+'!M'+rn, values:[[saved?'טלי':'']]});
    const src=norm(r[13]); if(saved&&src) writes.push({range:src, values:[['✅ טלי שימרה '+dm+' – העסקה של טלי']]});
    if(!/^שומר/.test(st)&&/^שומר/.test(norm(r[14]).split('|')[0])&&src) writes.push({range:src, values:[['➡️ אצל טלי – '+(st||'בטיפול')]]}); }
  if(FINAL.test(st)){ if(norm(r[9])!=='') writes.push({range:T+'!J'+rn, values:[['']]}); return; }
  const h=Math.floor(hrs(last,nowIL)); writes.push({range:T+'!J'+rn, values:[[h]]});
  const it={name, phone:norm(r[3]), rep:norm(r[4]).split(' ')[0], why:norm(r[5]).replace(/\s*\(חודש.*\)$/,''), h, st};
  openL.push(it);
  if(!quiet && !norm(r[10])){ newL.push(it); writes.push({range:T+'!K'+rn, values:[[nowS]]}); }
  const lb=parseS(r[11]);
  if(!quiet && h>=24 && (!lb||hrs(lb,nowIL)>=24)){ breachL.push(it); writes.push({range:T+'!L'+rn, values:[[nowS]]}); }
});
const line=(x,i)=>(i+1)+'. '+x.name+(x.phone?' '+x.phone:'')+' | '+x.rep+' | '+x.why;
const cap=(l,f)=>{ const o=l.slice(0,15).map(f); if(l.length>15) o.push('ועוד '+(l.length-15)); return o.join('\n'); };
const remDone=norm((tt[0]||[])[16])===todayIso;
const daily=!quiet && H>=9 && !remDone && openL.length>0;
if(!quiet && (newL.length||daily)){
  let m='🔴 שימורים לטיפולך\n\nהיי טלי';
  if(newL.length) m+=', '+(newL.length===1?'נכנס לקוח חדש שהנציג לא ענה עליו 24 שעות:':'נכנסו '+newL.length+' לקוחות חדשים שהנציג לא ענה עליהם 24 שעות:')+'\n'+cap(newL,line);
  const old=openL.filter(x=>!newL.includes(x));
  if(daily && old.length) m+='\n\n'+(newL.length?'ועוד פתוחים אצלך':', פתוחים אצלך')+' ('+old.length+'):\n'+cap(old,(x,i)=>line(x,i)+(x.st?' | '+x.st:'')+(x.h>=20?' | '+x.h+' שעות בלי עדכון':''));
  m+='\n\n'+((newL.length+(daily?openL.length-newL.length:0))===1?'תתקשרי אליו היום.':'תתקשרי אליהם היום.')+' בחוצץ "שימורים לטלי" בדוח המכר מעדכנים סטטוס והערה. אם שימרת, העסקה שלך.\nאם אין עדכון 24 שעות, זה עולה לירדן ולסטיב.';
  if(m.length>1990) m=m.slice(0,1985)+'…';
  msgs.push({phone:TALI, msg:m});
}
if(daily||(!quiet&&H>=9&&!remDone&&newL.length)) writes.push({range:T+'!Q1', values:[[todayIso]]});
if(breachL.length){
  MGR.forEach(([n,p])=>{ let m='⏰ חריגה בשימורים\n\nהיי '+n+', '+(breachL.length===1?'לקוח אחד אצל טלי בלי עדכון יותר מ-24 שעות:':breachL.length+' לקוחות אצל טלי בלי עדכון יותר מ-24 שעות:')+'\n'+cap(breachL,(x,i)=>line(x,i)+' | '+x.h+' שעות')+'\n\nהפירוט בחוצץ "שימורים לטלי" בדוח המכר.';
    if(m.length>1990) m=m.slice(0,1985)+'…'; msgs.push({phone:p, msg:m}); });
}
return {writeBody:JSON.stringify({valueInputOption:'RAW',data:writes}), writeCount:writes.length, msgs, msgCount:msgs.length,
  dbg:JSON.stringify({quiet, fresh:fresh.length, open:openL.length, new:newL.length, breach:breachL.length, daily})};
